<?php $req1 = Request::create('/api/mobile/sync/full', 'GET', ['page' => 1, 'per_page' => 100]); $c = app()->make('App\Http\Controllers\Api\SponsorshipSyncController'); $ids1 = array_map(function($x) { return $x->id; }, $c->getFullSync($req1)->getData()->data); $req2 = Request::create('/api/mobile/sync/full', 'GET', ['page' => 2, 'per_page' => 100]); $ids2 = array_map(function($x) { return $x->id; }, $c->getFullSync($req2)->getData()->data); $intersect = array_intersect($ids1, $ids2); echo 'Intersect count: ' . count($intersect);
